20 | /**
21 |  * Turns anything Bob calls a path into a repo-relative forward-slash path.
22 |  * git speaks repo-relative forward slashes. Without this the join silently
23 |  * returns zero files and every survival number reads 0%.
24 |  *
25 |  * The two inputs are NOT the same shape and differ four ways at once:
26 |  *   task.workspace         "file:c:\\Users\\USER\\bobtest"                  (scheme + backslashes)
27 |  *   _meta.changes key      "file:///c%3A/Users/USER/bobtest/calc.py"       (scheme + slashes + %3A)
28 |  * So the scheme is stripped from BOTH sides, the key is percent-decoded, and the
29 |  * comparison is case-insensitive (the drive letter's case differs between them).
30 |  *
31 |  * arguments.path, by contrast, is a bare relative filename in all 14 tool calls of
32 |  * the four real exports - the absolute-path branch is defensive, not observed.
33 |  */
34 | export function normalisePath(p, repoRoot) {
35 |   if (!p) return null;
36 |   let s = String(p).replace(/^file:\/*/i, '');
37 |   try { s = decodeURIComponent(s); } catch { /* not percent-encoded; use as-is */ }
38 |   s = s.replace(/\\/g, '/');
39 |   if (repoRoot) {
40 |     const root = String(repoRoot)
41 |       .replace(/^file:\/*/i, '')
42 |       .replace(/\\/g, '/')
43 |       .replace(/\/+$/, '');
44 |     if (root && s.toLowerCase().startsWith(root.toLowerCase() + '/')) s = s.slice(root.length + 1);
45 |   }
46 |   return s.replace(/^\.\//, '').replace(/^\/+/, '');
47 | }
