49 | /** Reads every bob_sessions/*.json and flattens their tasks[] into one list. */
50 | export function loadSessions(dir) {
51 |   const out = [];
52 |   for (const f of readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
53 |     let raw;
54 |     try {
55 |       raw = JSON.parse(readFileSync(path.join(dir, f), 'utf8'));
56 |     } catch (e) {
57 |       throw new Error(`bob_sessions/${f} is not valid JSON: ${e.message}`);
58 |     }
59 |     for (const entry of raw.tasks ?? []) {
60 |       out.push({ ...entry, _workspace: raw.workspace ?? null, _file: f });
61 |     }
62 |   }
63 |   // DEDUPE BY task.id. Bob tasks are resumable and the ritual exports "Current
64 |   // Task" every time, so re-opening a task to ask one follow-up produces a second
65 |   // file with the SAME task.id and a later updatedAt. Without this, totals.coins
66 |   // is inflated (and will not match the Bob panel at the H+11 checkpoint) and
67 |   // React sees duplicate keys in the table, scatter and context chart.
68 |   const byId = new Map();
69 |   for (const e of out) {
70 |     const id = e.task?.id;
71 |     if (!id) continue;
72 |     const prev = byId.get(id);
73 |     if (!prev || (e.task.updatedAt ?? 0) > (prev.task.updatedAt ?? 0)) byId.set(id, e);
74 |   }
75 |   return [...byId.values()];
76 | }
