78 | /**
79 |  * Splits a task's tool calls into writes and "could not tell". `permission` is a
80 |  * plain STRING ("read" | "edit") on toolUsage, one per tool-result message - it is
81 |  * NOT an object, so `permission.read` is undefined and any test on it is vacuous.
82 |  * The arguments.path guard is load-bearing: `glob` and `FindSymbol` are edit-less
83 |  * reads whose arguments.path is undefined.
84 |  */
85 | export function classifyTools(entry, repoRoot) {
86 |   const writes = [];
87 |   const unknownTools = [];
88 |   for (const m of entry.messages ?? []) {
89 |     const tu = m?.data?.toolUsage;
90 |     if (!tu) continue;
91 |     const sig = tu.signature ?? {};
92 |     const name = sig.name ?? '(unnamed)';
93 |     if (tu.permission === 'read') continue;
94 |     if (tu.permission !== 'edit') {
95 |       // A tool that admits what it could not attribute is more credible than one
96 |       // that reports 0%. Surfaced, never swallowed.
97 |       unknownTools.push({ name, reason: `unrecognised permission ${JSON.stringify(tu.permission)}` });
98 |       continue;
99 |     }
100 |     if (sig.isError === true) continue;
101 |     if (typeof sig.arguments?.path !== 'string') {
102 |       unknownTools.push({ name, reason: 'edit tool with no arguments.path' });
103 |       continue;
104 |     }
105 |     const p = normalisePath(sig.arguments.path, repoRoot);
106 |     if (p) writes.push({ name, path: p });
107 |   }
108 |   return { writes, unknownTools };
109 | }
