111 | /**
112 |  * Every file touched by a `_meta.changes` entry. Bob emits ONE entry per edit-tool
113 |  * RESULT, each an object with exactly one key; multiplicity appears ACROSS messages.
114 |  * Reading only the last change-bearing message loses edits, so scan them all.
115 |  */
116 | export function changedFiles(entry, repoRoot) {
117 |   const out = [];
118 |   for (const m of entry.messages ?? []) {
119 |     for (const key of Object.keys(m?.data?._meta?.changes ?? {})) {
120 |       const p = normalisePath(key, repoRoot);
121 |       if (p) out.push({ path: p, change: m.data._meta.changes[key] });
122 |     }
123 |   }
124 |   return out;
125 | }
