127 | /** JOIN #2: repo-relative paths this task successfully wrote to. */
128 | export function writtenFiles(entry, repoRoot) {
129 |   const seen = new Set(classifyTools(entry, repoRoot).writes.map((w) => w.path));
130 |   for (const c of changedFiles(entry, repoRoot)) seen.add(c.path);
131 |   return [...seen].sort();
132 | }
