134 | /**
135 |  * file -> the set of lines this task actually ADDED, from _meta.changes before/after.
136 |  * This is the evidence the authorship test runs on. A change with no before/after
137 |  * yields nothing, which makes the task unattributed rather than falsely credited.
138 |  */
139 | export function bobAddedLines(entry, repoRoot) {
140 |   const map = new Map();
141 |   for (const { path: f, change } of changedFiles(entry, repoRoot)) {
142 |     if (change?.after === undefined) continue;
143 |     const remaining = new Map();
144 |     for (const l of String(change.before ?? '').split('\n')) {
145 |       const k = l.trim();
146 |       if (k) remaining.set(k, (remaining.get(k) ?? 0) + 1);
147 |     }
148 |     const set = map.get(f) ?? new Set();
149 |     for (const l of String(change.after).split('\n')) {
150 |       const k = l.trim();
151 |       if (!k) continue;
152 |       const n = remaining.get(k) ?? 0;
153 |       if (n > 0) remaining.set(k, n - 1);
154 |       // Candidate lines under 4 chars are not evidence of authorship: "}", "{", ");"
155 |       // and "})" are the most-added lines in a TS/TSX repo, so a human commit touching
156 |       // the same file would match on a brace and be credited to Bob - collapsing the
157 |       // authorship half of the join. The 4-export corpus was Python, which never
158 |       // exposed this. Keep the multiset decrement above for ALL lines; only the
159 |       // authorship candidate set is filtered.
160 |       else if (k.length >= 4) set.add(k);
161 |     }
162 |     if (set.size) map.set(f, set);
163 |   }
164 |   return map;
165 | }
