173 | /** All commits reachable from HEAD, oldest first, author time in MILLISECONDS. */
174 | export function commitLog(repo) {
175 |   // %ct is COMMITTER time and it is the right field here: an author time can
176 |   // predate the task that produced the code (rebase, cherry-pick, git am,
177 |   // --date), and we are asking "which commit came after this task", which is
178 |   // a repo-state question.
179 |   const out = git(repo, ['log', '--format=%H %ct', 'HEAD']);
180 |   return out
181 |     .split(/\r?\n/)
182 |     .filter(Boolean)
183 |     .map((line) => {
184 |       const [sha, ct] = line.trim().split(' ');
185 |       return { sha, timeMs: Number(ct) * 1000 };
186 |     })
187 |     // `git log --reverse` reverses GRAPH order, not TIME order. They coincide
188 |     // only on a linear, never-amended history. Sorting explicitly removes the
189 |     // dependency on git's ordering: one out-of-order commit would otherwise
190 |     // mis-attribute every task after it, silently.
191 |     .sort((a, b) => a.timeMs - b.timeMs);
192 | }
