194 | /** file -> set of trimmed lines this commit ADDED. Trimmed, so CRLF cannot matter. */
195 | export function commitAddedLines(repo, sha) {
196 |   const out = git(repo, ['show', '--format=', '--unified=0', '--no-renames', '--first-parent', sha]);
197 |   const map = new Map();
198 |   let file = null;
199 |   for (const raw of out.split('\n')) {
200 |     const line = raw.replace(/\r$/, '');
201 |     if (line.startsWith('+++ ')) {
202 |       const t = line.slice(4).trim();
203 |       file = t === '/dev/null' ? null : t.replace(/^b\//, '');
204 |       continue;
205 |     }
206 |     if (line.startsWith('---') || line.startsWith('diff ') || line.startsWith('@@')) continue;
207 |     if (!file || !line.startsWith('+')) continue;
208 |     const k = line.slice(1).trim();
209 |     if (!k) continue;
210 |     if (!map.has(file)) map.set(file, new Set());
211 |     map.get(file).add(k);
212 |   }
213 |   return map;
214 | }
