216 | /**
217 |  * JOIN #1. gitSha in the export came back null on every task exported, so we join
218 |  * on time AND on content. Time alone is not a join: the first commit at or after a
219 |  * task's last update is just as likely to be a human's, and crediting it reports
220 |  * 100% survival on code that was thrown away. Two guards, both required:
221 |  *
222 |  *   1. UPPER BOUND - the commit must land within `windowMs` of the task.
223 |  *   2. AUTHORSHIP  - the commit must ADD at least one line the task's own
224 |  *      _meta.changes says Bob wrote. Measured: task da0e0ddc added a
225 |  *      divide-by-zero guard that was never committed; the next commit in time is
226 |  *      "C: human rewrites Bob's docstring", which shares none of Bob's lines.
227 |  *
228 |  * Both are mandatory: there is no 2-argument form, because the 2-argument form is
229 |  * the bug. A task whose commit cannot be found returns null and MUST be surfaced
230 |  * by the caller (see attributeTask), not dropped.
231 |  *
232 |  * Still true: batched commits collapse several tasks onto one commit and each
233 |  * would claim its full added-line count - assertUniqueCommits refuses that.
234 |  */
235 | export function commitForTask(commits, updatedAtMs, opts = {}) {
236 |   const { repo, entry, windowMs = DEFAULT_WINDOW_MS } = opts;
237 |   if (!repo || !entry) {
238 |     throw new Error('commitForTask(commits, updatedAtMs, { repo, entry }): the authorship test is not optional');
239 |   }
240 |   const bob = bobAddedLines(entry, opts.repoRoot ?? entry._workspace ?? entry.task?.workspace ?? null);
241 |   if (bob.size === 0) return null;
242 |   for (const c of commits) { // commitLog() is sorted by time, so we can stop early
243 |     if (c.timeMs < updatedAtMs) continue;
244 |     if (c.timeMs > updatedAtMs + windowMs) return null;
245 |     const added = commitAddedLines(repo, c.sha);
246 |     for (const [f, lines] of bob) {
247 |       const inCommit = added.get(f);
248 |       if (!inCommit) continue;
249 |       for (const l of lines) if (inCommit.has(l)) return { sha: c.sha, timeMs: c.timeMs, bobLines: bob };
250 |     }
251 |   }
252 |   return null;
253 | }
