255 | /** path -> lines added by this commit. Binary files (added === '-') are skipped. */
256 | export function addedLines(repo, sha) {
257 |   // --no-renames: since git 2.9 diff.renames defaults on, so a renamed file prints
258 |   // as "old.ts => new.ts" - a key that matches nothing from writtenFiles, silently
259 |   // shrinking the denominator. --first-parent keeps merge commits from printing
260 |   // zero file rows.
261 |   const out = git(repo, ['show', '--numstat', '--no-renames', '--format=', '--first-parent', sha]);
262 |   const map = new Map();
263 |   for (const line of out.split('\n')) {
264 |     const [added, , file] = line.split('\t');
265 |     if (!file || added === '-' || added === undefined) continue;
266 |     const p = file.trim().replace(/\\/g, '/');
267 |     map.set(p, (map.get(p) ?? 0) + Number(added));
268 |   }
269 |   return map;
270 | }
271 | 
272 | /** Lines of `file` still present at HEAD that blame to `sha`. */
273 | export function survivingLines(repo, sha, file) {
274 |   try {
275 |     git(repo, ['cat-file', '-e', `HEAD:${file}`]);
276 |   } catch {
277 |     return 0; // deleted or renamed at HEAD -> nothing survived. Documented limit.
278 |   }
279 |   let out;
280 |   try {
281 |     // -w -M -C are not optional: without them one `black .` / prettier run late in
282 |     // the build re-indents everything, every line blames to the formatter commit,
283 |     // and every task collapses to ~0% survival with no error.
284 |     out = git(repo, ['blame', '-w', '-M', '-C', '--line-porcelain', 'HEAD', '--', file]);
285 |   } catch {
286 |     return 0;
287 |   }
288 |   let n = 0;
289 |   for (const line of out.split('\n')) {
290 |     // Porcelain record header: "<sha> <orig> <final>[ <count>]".
291 |     // Content lines are TAB-prefixed, so they cannot match this anchor.
292 |     const m = /^([0-9a-f]{40}) \d+ \d+(?: \d+)?$/.exec(line);
293 |     if (m && m[1] === sha) n++;
294 |   }
295 |   return n;
296 | }
297 | 
298 | /**
299 |  * Trimmed contents of the lines at HEAD in `file` that blame to `sha`.
300 |  * survivingLines() returns only a COUNT, and a count cannot be intersected with
301 |  * Bob's own authored set - which is why the task-level numerator needs this.
302 |  * --line-porcelain emits one TAB-prefixed content line per record, after its header.
303 |  */
304 | export function survivingLineSet(repo, sha, file) {
305 |   const out = new Set();
306 |   try { git(repo, ['cat-file', '-e', `HEAD:${file}`]); } catch { return out; }
307 |   let blame;
308 |   try {
309 |     blame = git(repo, ['blame', '-w', '-M', '-C', '--line-porcelain', 'HEAD', '--', file]);
310 |   } catch { return out; }
311 |   let armed = false;
312 |   for (const line of blame.split('\n')) {
313 |     const m = /^([0-9a-f]{40}) \d+ \d+(?: \d+)?$/.exec(line);
314 |     if (m) { armed = m[1] === sha; continue; }
315 |     if (armed && line.startsWith('\t')) {
316 |       const k = line.slice(1).trim();
317 |       if (k) out.add(k);
318 |       armed = false;
319 |     }
320 |   }
321 |   return out;
322 | }
323 | 
324 | /**
325 |  * Survival for one task. TASK-LEVEL when `bobLines` is supplied (the normal path,
326 |  * and what every shipped doc claims): the denominator is every line THIS TASK
327 |  * wrote, and the numerator is how many of those exact lines are still attributed
328 |  * to `sha` at HEAD. Result carries `level: 'task'`.
329 |  *
330 |  * Falls back to the older COMMIT-LEVEL ratio (every line the commit added vs what
331 |  * survives at HEAD) only for callers with no line set — see the note below for why
332 |  * that ratio misreports a commit that mixes Bob and human lines.
333 |  */
334 | export function taskSurvival(repo, sha, files, bobLines) {
335 |   // bobLines (returned by commitForTask) switches the denominator from "every line
336 |   // this COMMIT added" to "every line THIS TASK wrote" - which is what README-DRAFT,
337 |   // the long description and USAGE-STATEMENT all claim. Without it, a commit mixing
338 |   // 1 Bob line with 9 human lines reports authored=10, so a task whose contribution
339 |   // was fully reverted can render ~90% survived and one that fully survived ~10%.
340 |   // The commit-level path below is kept for callers that have no line set.
341 |   if (bobLines && bobLines.size) {
342 |     let authored = 0, survived = 0;
343 |     const per = [];
344 |     const unmatched = [];
345 |     for (const f of files) {
346 |       const mine = bobLines.get(f);
347 |       // A file Bob wrote but whose lines we cannot locate (path drift, case drift,
348 |       // rename) must be SURFACED, not scored 0/0 - scoring it silently is the
349 |       // "confident wrong number" failure the commit-level path guarded against.
350 |       if (!mine || mine.size === 0) { unmatched.push(f); continue; }
351 |       const alive = survivingLineSet(repo, sha, f);
352 |       let hit = 0;
353 |       for (const l of mine) if (alive.has(l)) hit++;
354 |       authored += mine.size; survived += hit;
355 |       per.push({ file: f, authored: mine.size, survived: hit });
356 |     }
357 |     return {
358 |       authored, survived,
359 |       pct: authored ? survived / authored : null,
360 |       files: per.sort((x, y) => y.authored - x.authored),
361 |       unmatched,
362 |       level: 'task',
363 |     };
364 |   }
365 |   const added = addedLines(repo, sha);
366 |   let authored = 0, survived = 0;
367 |   const per = [];
368 |   // Every written file this commit does not account for lands here instead of
369 |   // vanishing. Surfaced in analysis.json and rendered as the unattributed rate.
370 |   const unmatched = [];
371 |   for (const f of files) {
372 |     const a = added.get(f) ?? 0;
373 |     if (a === 0) {
374 |       // THE master silent-zero. This one line swallows: absolute paths that were
375 |       // never relativised, case drift (the build box is case-insensitive NTFS so
376 |       // nothing else catches it), rename-mangled keys, and files the commit did
377 |       // not include. A PARTIAL mismatch is the dangerous case: it yields a
378 |       // confident non-zero percentage computed over a subset of the files.
379 |       // Never swallow it silently.
380 |       unmatched.push(f);
381 |       continue;
382 |     }
383 |     const s = Math.min(survivingLines(repo, sha, f), a);
384 |     authored += a; survived += s;
385 |     per.push({ file: f, authored: a, survived: s });
386 |   }
387 |   return {
388 |     authored, survived,
389 |     pct: authored ? survived / authored : null,
390 |     files: per.sort((x, y) => y.authored - x.authored),
391 |     unmatched,
392 |   };
393 | }
394 | const _logCache = new Map();
395 | 
396 | /**
397 |  * The whole join for one task, with nowhere for a task to vanish. Every task that
398 |  * goes in comes out; when it has no commit it carries `unattributed` saying why
399 |  * instead of disappearing between commitForTask() and the results table.
400 |  * `unmatched` only ever caught path mismatches, so no-commit tasks used to be
401 |  * invisible - 4 tasks in, 2 rows out, no error.
402 |  */
403 | export function attributeTask(repo, entry, opts = {}) {
404 |   const t = entry.task ?? {};
405 |   const root = entry._workspace ?? t.workspace ?? null;
406 |   const { unknownTools } = classifyTools(entry, root);
407 |   const files = writtenFiles(entry, root);
408 | 
409 |   if (!_logCache.has(repo)) _logCache.set(repo, commitLog(repo));
410 |   const commits = opts.commits ?? _logCache.get(repo);
411 | 
412 |   let commit = null;
413 |   let unattributed = null;
414 |   if (files.length === 0) unattributed = 'no-files-written';
415 |   else if (!t.updatedAt) unattributed = 'no-updatedAt';
416 |   else {
417 |     commit = commitForTask(commits, t.updatedAt, { repo, entry, repoRoot: root, windowMs: opts.windowMs });
418 |     if (!commit) unattributed = 'no-matching-commit';
419 |   }
420 | 
421 |   // commit.bobLines is what makes this TASK-level rather than commit-level. Drop the
422 |   // 4th argument and taskSurvival silently falls back to counting every line the
423 |   // commit added, which inverts the metric on any mixed-authorship commit.
424 |   const surv = commit
425 |     ? taskSurvival(repo, commit.sha, files, commit.bobLines)
426 |     : { authored: 0, survived: 0, pct: null, files: [], unmatched: files };
427 | 
428 |   return {
429 |     id: String(t.id ?? entry._file),
430 |     wroteFiles: files,
431 |     commit: commit ? { sha: commit.sha, short: commit.sha.slice(0, 7), timeMs: commit.timeMs } : null,
432 |     authored: surv.authored,
433 |     survived: surv.survived,
434 |     survivalPct: surv.pct,
435 |     fileBreakdown: surv.files,
436 |     unmatchedFiles: surv.unmatched,
437 |     unattributed,
438 |     unknownTools,
439 |   };
440 | }
441 | 
442 | /** One commit cannot be two tasks' work: each would claim its full added-line count. */
443 | export function assertUniqueCommits(tasks) {
444 |   const bySha = new Map();
445 |   for (const t of tasks) {
446 |     const sha = t.commit?.sha;
447 |     if (!sha) continue;
448 |     if (!bySha.has(sha)) bySha.set(sha, []);
449 |     bySha.get(sha).push(t.id);
450 |   }
451 |   const clashes = [...bySha].filter(([, ids]) => ids.length > 1);
452 |   if (clashes.length === 0) return;
453 |   throw new Error(
454 |     'JOIN #1 collision: a commit is claimed by more than one task\n'
455 |     + clashes.map(([sha, ids]) => `  ${sha} claimed by ${ids.join(', ')}`).join('\n'),
456 |   );
457 | }
